mkdir -p /tmp/txt && cd /workspace/documents && for f in *.docx; do pandoc "$f" -t plain --wrap=none -o /tmp/txt/${f%.docx}.txt; done
python3 -I - <<'E'
import openpyxl,glob,os
from pptx import Presentation
for f in glob.glob('/workspace/documents/*.xlsx'):
    wb=openpyxl.load_workbook(f)
    out=open('/tmp/txt/'+os.path.basename(f)[:-5]+'.txt','w')
    for ws in wb:
        out.write(f'## SHEET {ws.title}\n')
        for r in ws.iter_rows():
            v=[(str(c.value) if c.value is not None else '') for c in r]
            if any(v): out.write(' | '.join(v)+'\n')
        for r in ws.iter_rows():
            for c in r:
                if c.comment: out.write(f'COMMENT {c.coordinate}: {c.comment.text}\n')
for f in glob.glob('/workspace/documents/*.pptx'):
    p=Presentation(f); out=open('/tmp/txt/'+os.path.basename(f)[:-5]+'.txt','w')
    for i,s in enumerate(p.slides,1):
        out.write(f'## SLIDE {i}\n')
        for sh in s.shapes:
            if sh.has_text_frame: out.write(sh.text_frame.text+'\n')
            if sh.has_table:
                for r in sh.table.rows: out.write(' | '.join(c.text for c in r.cells)+'\n')
        if s.has_notes_slide: out.write('NOTES: '+s.notes_slide.notes_text_frame.text+'\n')
E
cp *.eml /tmp/txt/; wc -c /tmp/txt/*

